import 'package:flutter/material.dart';
import '../data/app_database.dart';
enum EntityKind{customers,suppliers,expenses,fuelTanks}
class EntityPage extends StatefulWidget{const EntityPage({super.key,required this.kind});final EntityKind kind;@override State<EntityPage> createState()=>_S();}
class _S extends State<EntityPage>{List<Map<String,Object?>> rows=[];bool loading=true;String get title=>switch(widget.kind){EntityKind.customers=>'Customers',EntityKind.suppliers=>'Suppliers',EntityKind.expenses=>'Expenses',EntityKind.fuelTanks=>'Oil / Fuel Tanks'};Future<void> load()async{final d=AppDatabase.instance;rows=switch(widget.kind){EntityKind.customers=>await d.listCustomers(),EntityKind.suppliers=>await d.listSuppliers(),EntityKind.expenses=>await d.listExpenses(),EntityKind.fuelTanks=>await d.listFuelTanks()};if(mounted)setState(()=>loading=false);} @override void initState(){super.initState();load();}
Future<void> add()async{final a=TextEditingController(),b=TextEditingController(),c=TextEditingController();final ok=await showDialog<bool>(context:context,builder:(x)=>AlertDialog(title:Text('Add $title'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:a,decoration:InputDecoration(labelText:widget.kind==EntityKind.expenses?'Expense name':'Name')),TextField(controller:b,decoration:InputDecoration(labelText:widget.kind==EntityKind.expenses?'Amount':widget.kind==EntityKind.fuelTanks?'Capacity':'Phone')),TextField(controller:c,decoration:InputDecoration(labelText:widget.kind==EntityKind.fuelTanks?'Fuel type':widget.kind==EntityKind.expenses?'Note':'Address'))]),actions:[TextButton(onPressed:()=>Navigator.pop(x,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(x,true),child:const Text('Save'))]));if(ok!=true||a.text.trim().isEmpty)return;final d=AppDatabase.instance;switch(widget.kind){case EntityKind.customers:await d.saveCustomer(name:a.text.trim(),phone:b.text.trim(),address:c.text.trim());case EntityKind.suppliers:await d.saveSupplier(name:a.text.trim(),phone:b.text.trim(),address:c.text.trim());case EntityKind.expenses:await d.saveExpense(name:a.text.trim(),amount:double.tryParse(b.text)??0,note:c.text.trim());case EntityKind.fuelTanks:await d.saveFuelTank(name:a.text.trim(),fuelType:c.text.trim().isEmpty?'Petrol':c.text.trim(),capacity:double.tryParse(b.text)??0);}await load();}
@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:Text(title)),floatingActionButton:FloatingActionButton.extended(onPressed:add,icon:const Icon(Icons.add),label:const Text('Add')),body:loading?const Center(child:CircularProgressIndicator()):rows.isEmpty?Center(child:Text('No $title yet.')):ListView.separated(itemCount:rows.length,separatorBuilder:(_,__)=>const Divider(),itemBuilder:(_,i){final r=rows[i];return ListTile(title:Text('${r['name']}'),subtitle:Text(widget.kind==EntityKind.expenses?'Amount: ${r['amount']}':widget.kind==EntityKind.fuelTanks?'${r['fuel_type']} • ${r['current_stock']} / ${r['capacity']}':'${r['phone']??''} • ${r['address']??''}'));}));}
